import{_ as a,c as o,o as i,af as r}from"./chunks/framework.D84OZdX2.js";const u=JSON.parse('{"title":"PetLoss – Privacy Policy","description":"Privacy policy for PetLoss, a private and offline pet memorial & grief support app.","frontmatter":{"title":"PetLoss – Privacy Policy","description":"Privacy policy for PetLoss, a private and offline pet memorial & grief support app."},"headers":[],"relativePath":"en/privacy.md","filePath":"en/privacy.md"}'),t={name:"en/privacy.md"};function s(l,e,n,c,p,h){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="petloss-–-privacy-policy" tabindex="-1">PetLoss – Privacy Policy <a class="header-anchor" href="#petloss-–-privacy-policy" aria-label="Permalink to “PetLoss – Privacy Policy”">​</a></h1><p>Last updated: 2025-01-18</p><p>PetLoss is a private, offline app for pet memorials and grief support. This policy explains what data the app handles and how it is used.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><ul><li>No account or sign-in required.</li><li>No ads, analytics SDKs, or third-party trackers.</li><li>Your memorials and journal entries stay on your device.</li><li>Photos are accessed only when you choose to import or save.</li><li>Network access is used only for App Store purchases/restores or when you open external links or email support.</li></ul><h2 id="data-stored-on-your-device" tabindex="-1">Data Stored on Your Device <a class="header-anchor" href="#data-stored-on-your-device" aria-label="Permalink to “Data Stored on Your Device”">​</a></h2><p>To provide core features, we store the following locally:</p><ul><li>Memorial projects (pet name, dates, notes), templates, and settings.</li><li>Imported photos and the exports you create.</li><li>Journal entries and healing prompts history.</li><li>Purchase status (Pro entitlement) cached on device.</li><li>Reminder preferences for optional notifications.</li></ul><p>You can delete a project in the app or remove all data by deleting the app.</p><h2 id="photos-files" tabindex="-1">Photos &amp; Files <a class="header-anchor" href="#photos-files" aria-label="Permalink to “Photos &amp; Files”">​</a></h2><p>PetLoss requests photo library access only when you choose to import or save media. Selected photos are copied into the app’s sandbox for offline use. Backups and exports are saved to Files only when you choose a location.</p><h2 id="in-app-purchases" tabindex="-1">In-App Purchases <a class="header-anchor" href="#in-app-purchases" aria-label="Permalink to “In-App Purchases”">​</a></h2><p>Purchases are processed by Apple via StoreKit. We do not receive your payment information. Apple may process purchase history according to its own policies.</p><h2 id="what-we-do-not-collect" tabindex="-1">What We Do Not Collect <a class="header-anchor" href="#what-we-do-not-collect" aria-label="Permalink to “What We Do Not Collect”">​</a></h2><ul><li>No personal identifiers (name, email, phone, precise location).</li><li>No contacts, camera, microphone, or calendar access.</li><li>No advertising identifiers or behavioral tracking.</li></ul><h2 id="optional-support-email" tabindex="-1">Optional Support Email <a class="header-anchor" href="#optional-support-email" aria-label="Permalink to “Optional Support Email”">​</a></h2><p>If you contact us at <a href="mailto:riends@petloss.app" target="_blank" rel="noreferrer">riends@petloss.app</a>, the email is sent by your mail app. You control what you share and can remove any information before sending.</p><h2 id="children-s-privacy" tabindex="-1">Children’s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to “Children’s Privacy”">​</a></h2><p>The app is rated 4+ and intended for a general audience. We do not knowingly collect personal information from children.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h2><p>Your data stays on your device within the iOS sandbox. Please keep your device updated and protected.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to “Changes to This Policy”">​</a></h2><p>We may update this policy as the app evolves. Material changes will be reflected by updating the “Last updated” date above and publishing the new version at this URL.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>If you have questions about privacy or this app, please contact: <a href="mailto:riends@petloss.app" target="_blank" rel="noreferrer">riends@petloss.app</a></p>',25)])])}const m=a(t,[["render",s]]);export{u as __pageData,m as default};
